#!/usr/bin/env python3
"""Read-only exact value reuse audit of validated AIT1 tails; no models/engine/profilers."""
from pathlib import Path
import collections,datetime,hashlib,html,importlib.util,json,os,statistics
ROOT=Path(__file__).resolve().parent
SPEC=importlib.util.spec_from_file_location('wire',ROOT/'replay-wire-analysis.py');wire=importlib.util.module_from_spec(SPEC);SPEC.loader.exec_module(wire)
def sha(path):
 with path.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def analyze(record):
 path=Path(record['replay_path']);assert sha(path)==record['replay_sha256'];data=path.read_bytes();tail=wire.parse(data,record['tail_offset']);assert tail['wire_bytes']==record['tail_wire_bytes'];assert tail['logical_budget_used']==record['logical_budget_used']
 values=collections.Counter();joint=collections.Counter();lengths=collections.Counter();row_duplicates=0;metadata_duplicates=0;rows=0;slots=0
 for step,changes in tail['frames']:
  for team,player,name,available,fields in changes:
   rows+=1;vc=collections.Counter(v[1] for v in fields);row_duplicates+=sum(n-1 for n in vc.values())
   metadata_duplicates+=len(fields)-len({(v[0],v[2],v[3]) for v in fields})
   for n,v,u,m,updated in fields:
    values[v]+=1;joint[((n,u,m),v)]+=1;lengths[len(v)]+=1;slots+=1
 assert slots==record['counts']['values_total'];assert sum(len(v)*n for v,n in values.items())==record['counts']['value_text_bytes']
 n=len(values);unique_text=sum(map(len,values));ordered_fingerprint=hashlib.sha256()
 # Audit fingerprint includes frame/row identity, value vector position and exact values/updated; no set ordering substitutes for history.
 import struct
 for step,changes in tail['frames']:
  ordered_fingerprint.update(struct.pack('>II',step,len(changes)))
  for team,player,name,available,fields in changes:
   ordered_fingerprint.update(struct.pack('>III',team,player,len(fields)))
   for position,(_,v,_,_,updated) in enumerate(fields):ordered_fingerprint.update(struct.pack('>III',position,len(v),updated));ordered_fingerprint.update(v)
 occurrence_short=sum(count for length,count in lengths.items() if length<=15);unique_short=sum(len(v)<=15 for v in values)
 # Alternative valueID + schemaID + updated = three Uint32 fields (12bytes, uncompiled/unmeasured assumption).
 theoretical_id_bytes=12*slots;actual_compact_value_bytes=40*slots
 model=json.loads((ROOT/'telemetry-storage-model/summary.json').read_text())
 compact=next(r['native'] for r in model['records'] if r['case']['input_case']==record['case'] and r['case']['mode']=='intern-reserve')
 assert compact['value_slots']==slots and compact['sizeof_compact_value']==40
 result=dict(input_case=record['case'],replay_sha256=record['replay_sha256'],tail_sha256=record['tail_sha256'],tail_offset=record['tail_offset'],tail_wire_bytes=record['tail_wire_bytes'],values_total=slots,row_records=rows,unique_exact_value_strings=n,unique_value_text_bytes=unique_text,repeated_value_text_bytes=sum(len(v)*c for v,c in values.items()),unique_value_length_prefixed_bytes=unique_text+4*n,repeated_value_length_prefixed_bytes=sum(len(v)*c for v,c in values.items())+4*slots,empty_value_occurrences=values[b''],unique_empty_values=int(b'' in values),NUL_value_occurrences=sum(c for v,c in values.items() if b'\0' in v),unique_values_with_NUL=sum(b'\0' in v for v in values),repeated_same_value_occurrences_within_rows=row_duplicates,duplicate_metadata_occurrences_within_rows=metadata_duplicates,value_occurrences_SSO_length_eligible_15=occurrence_short,value_occurrences_longer_than_15=slots-occurrence_short,unique_values_SSO_length_eligible_15=unique_short,unique_values_longer_than_15=n-unique_short,length_histogram={str(k):v for k,v in sorted(lengths.items())},unique_metadata_value_pairs=len(joint),ordered_value_updated_fingerprint_sha256=ordered_fingerprint.hexdigest(),values=[dict(exact_hex=v.hex(),display=v.decode('utf-8','backslashreplace'),text_bytes=len(v),occurrences=c) for v,c in values.most_common()],hypothetical_storage=dict(measured_compact_value_ABI_bytes=40,actual_compact_populated_value_object_bytes=actual_compact_value_bytes,unmeasured_ID_value_assumption_bytes=12,measured_compact_total_vector_capacity_bytes=compact['storage_vector_capacity_bytes'],hypothetical_exact_capacity_ID_vector_bytes=theoretical_id_bytes,hypothetical_total_vector_capacity_same_row_frame_slots_bytes=compact['storage_vector_capacity_bytes']-actual_compact_value_bytes+theoretical_id_bytes,arithmetic_value_object_capacity_difference_bytes=actual_compact_value_bytes-theoretical_id_bytes,hypothetical_value_dictionary_std_string_objects_32bytes=32*n,hypothetical_value_dictionary_text_bytes=unique_text,source_metadata_unique_text_bytes=record['metadata']['unique_text_bytes'],source_metadata_triples=record['metadata']['unique_exact_triples'],exclude='Allocator headers, hash table keys/nodes/buckets, ID lookup, dictionary lifetime/reclamation, update/delta indexes and engine integration; no compiled12byte ABI or measured RSS/CPU savings'))
 return result

def main():
 os.sched_setaffinity(0,{15,31});source=ROOT/'replay-wire-analysis.json';verified=json.loads(source.read_text());cases=[analyze(r) for r in verified['cases']]
 result=dict(generated_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),source_sha256=sha(Path(__file__)),wire_analysis_sha256=sha(source),wire_parser_sha256=sha(ROOT/'replay-wire-analysis.py'),measured_model_summary_sha256=sha(ROOT/'telemetry-storage-model/summary.json'),libstdcpp_SSO_source=dict(path='/usr/include/c++/13/bits/basic_string.h',sha256=sha(Path('/usr/include/c++/13/bits/basic_string.h')),rule='_S_local_capacity = 15 / sizeof(_CharT)'),cases=cases,limits=['Exact byte values preserve empty strings, NUL, duplicate occurrences, order and updated timestamps. No Unicode/numeric normalization. Histograms/dictionaries summarize redundancy; they do not replace the original ordered payload.','Length<=15 is SSO eligibility for this GCC13/libstdc++ ABI, not live-engine capacity measurement. The observed compact model40byte object already includes32byte std::string storage even when text is short.','12byte schemaID/valueID/updated arithmetic is an uncompiled hypothetical object capacity, not an engine layout, measured peak, RSS saving or CPU speedup. Dictionary/search/refcount/decode overhead is unknown.','Current AIT1 writer already stores changed rows, not every game tick. Most positional value/update pairs remain unchanged, but update-only timestamps and schema shifts must be represented exactly.','Interning/deltas must reconstruct exactly the existing completeAIT1 payload and its original until/truncated state. Lower internal memory must not silently extend recorded history or change limits/file acceptance.','Future qualification would require current game trace, exact fullreplay AIT1/order bytes, seek/application, save/load continuation, malformed-input budgets, and affectedplatforms. No model/engine/build/profiler children launched.'])
 (ROOT/'replay-value-analysis.json').write_text(json.dumps(result,indent=2)+'\n')
 sections=[]
 for c in cases:
  h=c['hypothetical_storage'];fields=[('Value occurrences / distinct exact strings',f"{c['values_total']:,} / {c['unique_exact_value_strings']:,}"),('Repeated / unique text bytes',f"{c['repeated_value_text_bytes']:,} / {c['unique_value_text_bytes']:,}"),('SSO length eligible occurrences / longer than15',f"{c['value_occurrences_SSO_length_eligible_15']:,} / {c['value_occurrences_longer_than_15']:,}"),('Empty / embeddedNUL occurrences',f"{c['empty_value_occurrences']:,} / {c['NUL_value_occurrences']:,}"),('Repeated equal value occurrences within rows',f"{c['repeated_same_value_occurrences_within_rows']:,}"),('Actual compact value object bytes (40each)',f"{h['actual_compact_populated_value_object_bytes']:,}"),('Hypothetical ID value bytes (12each)',f"{h['hypothetical_exact_capacity_ID_vector_bytes']:,}"),('Hypothetical unique value std::string object bytes',f"{h['hypothetical_value_dictionary_std_string_objects_32bytes']:,}")]
  sections.append('<section><h2>'+html.escape(c['input_case'])+'</h2><table>'+''.join('<tr><th>'+html.escape(k)+'</th><td>'+html.escape(v)+'</td></tr>' for k,v in fields)+'</table></section>')
 page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Exact telemetry value reuse</title><style>body{font:16px/1.55 system-ui;max-width:1000px;margin:36px auto;padding:0 22px}section{border:1px solid #ddd;padding:20px;margin:20px 0}th,td{padding:7px;text-align:left}.notice{background:#fff4dc;padding:16px}</style><h1>Exact telemetry value-string reuse</h1><p>Read-only audit of two existing frozen legacyAIT1 tails. Exact metadata triples and exact values may share immutable storage while preserving ordered value IDs, timestamps and every original frame/row byte.</p><p class="notice">Value-ID and delta capacity figures below are hypothetical and unmeasured. They omit dictionary/lifetime/integration costs and imply no whole-engine RSS or CPU saving.</p>'+''.join(sections)+'<h2>Does further lossless compaction merit a future control?</h2><p>Repeated short values occupy many full std::string objects in the40byte compact model even when they allocate no external text buffer. Exact value IDs could reduce that object capacity, and internal deltas could avoid many unchanged positional records. Each still needs exact handling of update-only changes, duplicate fields and schema changes. A future game plan should test reconstruction and integration costs before memory/timing claims; this audit adds no experiment or production layout change.</p><ul>'+''.join('<li>'+html.escape(v)+'</li>' for v in result['limits'])+'</ul><p><a href="replay-value-analysis.json">Exact values/hex counts and assumptions</a> · <a href="replay-value-analysis.py">Read-only parser analysis</a> · <a href="replay-wire-analysis.html">Metadata/history wire audit</a> · <a href="telemetry-storage-model/model-analysis.html">Existing compact-model measurements</a></p></html>'
 (ROOT/'replay-value-analysis.html').write_text(page)
 for c in cases:print(c['input_case'],{k:v for k,v in c.items() if k in ['values_total','unique_exact_value_strings','unique_value_text_bytes','repeated_value_text_bytes','value_occurrences_SSO_length_eligible_15','empty_value_occurrences','NUL_value_occurrences','repeated_same_value_occurrences_within_rows']})
if __name__=='__main__':main()
